package com.nm.fragmentsclean.experienceContext.write.adapters.primary.springboot.scheduling;
import com.nm.fragmentsclean.experienceContext.write.businesslogic.usecases.CleanExperienceMediaObjects;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="fragments.media.cleanup",name="enabled",havingValue="true") public final class ExperienceMediaCleanupJob{private final CleanExperienceMediaObjects cleanup;public ExperienceMediaCleanupJob(CleanExperienceMediaObjects cleanup){this.cleanup=cleanup;}@Scheduled(fixedDelayString="${fragments.media.cleanup.delay-ms:600000}")public void clean(){cleanup.run(100);}}
